/** MINI-HQ B1 — custom message media regression. No network, no database, no sends. */
import { readFileSync } from "node:fs";
import {
  CUSTOM_MEDIA_MAX_BYTES,
  customMediaEntitled,
  customMediaStoragePath,
  inspectCustomMedia,
  isCustomMediaSlot,
  isWorkspaceCustomMediaPath,
} from "../src/lib/custom-message-media";

let passed = 0;
const failures: string[] = [];
const check = (n: string, c: boolean) => (c ? passed++ : failures.push(n));

// ---- REAL tiny image fixtures (generated by Pillow, embedded verbatim)
const b64 = (s: string) => new Uint8Array(Buffer.from(s, "base64"));
const PNG = b64("iVBORw0KGgoAAAANSUhEUgAAAAMAAAACCAIAAAASFvFNAAAAFUlEQVR4nGO8skKLgYGBgYGBiQEGAB6SAaoMEkBsAAAAAElFTkSuQmCC");
const JPG = b64("");
const GIF = b64("R0lGODdhBAAEAIAAAAAAAAAAACwAAAAABAAEAAAICQABCBxIsCCAgAA7");
// animated = same header+table + the frame block twice + trailer
const FRAME = GIF.subarray(19, GIF.length - 1);
const AGIF = new Uint8Array([...GIF.subarray(0, 19), ...FRAME, ...FRAME, ...FRAME, 0x3b]);
const R = (b: Uint8Array) => inspectCustomMedia(b) as { ok: boolean; reason?: string; kind?: string; width?: number; height?: number; animated?: boolean };
const cat = (...a: (Uint8Array | number[])[]) => new Uint8Array(a.flatMap((x) => [...x]));

const p = R(PNG);
check("real PNG accepted 3x2", p.ok && p.kind === "png" && p.width === 3 && p.height === 2 && !p.animated);
const j = R(JPG);
check("real JPEG accepted 3x2", j.ok && j.kind === "jpeg" && j.width === 3 && j.height === 2);
const g1 = R(GIF);
check("real static GIF accepted", g1.ok && g1.kind === "gif" && g1.width === 4 && !g1.animated);
const g2 = R(AGIF);
check("3-frame GIF detected animated", g2.ok && g2.animated === true);
// structural rejections (previously accepted)
check("PNG IHDR-only 33 bytes rejected", !R(PNG.subarray(0, 33)).ok);
check("PNG 24-byte header rejected", !R(PNG.subarray(0, 24)).ok);
check("PNG missing IEND rejected", !R(PNG.subarray(0, PNG.length - 12)).ok);
check("PNG trailing junk rejected", !R(cat(PNG, [0])).ok);
const badCrc = PNG.slice(); badCrc[40] = (badCrc[40] ?? 0) ^ 0xff;
check("PNG corrupted IDAT (CRC) rejected", !R(badCrc).ok);
const noIdat = cat(PNG.subarray(0, 33), PNG.subarray(PNG.length - 12));
check("PNG with no IDAT rejected", !R(noIdat).ok);
const sofAt = JPG.indexOf(0xc0, 2) - 1;
check("JPEG SOF-only (no SOS/EOI) rejected", !R(cat(JPG.subarray(0, sofAt + 19), [0xff, 0xd9])).ok);
check("JPEG missing EOI rejected", !R(JPG.subarray(0, JPG.length - 2)).ok);
const sosAt = JPG.lastIndexOf(0xda) - 1;
check("JPEG SOS without scan data rejected", !R(cat(JPG.subarray(0, sosAt + 14), [0xff, 0xd9])).ok);
check("GIF zero frames rejected", !R(cat(GIF.subarray(0, 19), [0x3b])).ok);
check("GIF missing trailer rejected", !R(GIF.subarray(0, GIF.length - 1)).ok);
check("GIF truncated mid-frame rejected", !R(GIF.subarray(0, 25)).ok);
const oob = GIF.slice(); oob[19 + 5] = 9; // frame width 9 > screen 4
check("GIF frame outside screen rejected", !R(oob).ok);
const zf = GIF.slice(); zf[19 + 5] = 0;
check("GIF zero-size frame rejected", !R(zf).ok);
check("GIF frame with empty image data rejected", !R(cat(GIF.subarray(0, 19 + 11), [0, 0x3b])).ok);
check("spoofed PNG signature + text rejected", !R(cat(PNG.subarray(0, 8), new TextEncoder().encode("<script>"))).ok);
check("spoofed GIF header only rejected", !R(new TextEncoder().encode("GIF89a")).ok);
check("SVG rejected", !R(new TextEncoder().encode('<svg xmlns="http://www.w3.org/2000/svg"/>')).ok);
check("WebP rejected", !R(new TextEncoder().encode("RIFF\0\0\0\0WEBPVP8 ")).ok);
check("empty rejected", R(new Uint8Array()).reason === "empty");
const big = new Uint8Array(CUSTOM_MEDIA_MAX_BYTES + 1); big.set(PNG);
check("over 2 MiB rejected", R(big).reason === "too_large");
const wide = GIF.slice(); wide[6] = 0x88; wide[7] = 0x13; // 5000 px
check("GIF over 4096 px rejected", R(wide).reason === "bad_dimensions");

// ---- entitlement: executable matrix against the LIVE RPC result shape
const PRO = { allowed: true, reason: "FEATURE_INCLUDED", would_block: false, feature_key: "official_broadcasts", plan_code: "cartel_49", kind: "feature", enabled: true, assignment_status: "active", mode: "enforce", enforcement_mode: "enforce" };
const E = (o: Record<string, unknown>) => customMediaEntitled({ ...PRO, ...o });
const omit = (k: string) => { const c: Record<string, unknown> = { ...PRO }; delete c[k]; return customMediaEntitled(c); };
check("owner UNRESTRICTED allowed", customMediaEntitled({ allowed: true, reason: "UNRESTRICTED", mode: "unrestricted", would_block: false }));
check("Pro active allowed", customMediaEntitled(PRO));
check("Pro trialing allowed", E({ assignment_status: "trialing" }));
check("REVIEW BLOCKER: {allowed,plan_code} alone denied", !customMediaEntitled({ allowed: true, plan_code: "cartel_49" }));
check("inactive (canceled) denied", !E({ assignment_status: "canceled" }));
check("past_due denied", !E({ assignment_status: "past_due" }));
check("observe would_block denied", !E({ mode: "observe", enforcement_mode: "observe", would_block: true }));
check("would_block missing denied", !omit("would_block"));
check("would_block 'false' string denied", !E({ would_block: "false" }));
check("wrong feature_key denied", !E({ feature_key: "x_missions" }));
check("enabled missing/false denied", !omit("enabled") && !E({ enabled: false }));
check("kind quota denied", !E({ kind: "quota" }));
check("reason WITHIN_LIMIT denied", !E({ reason: "WITHIN_LIMIT" }));
check("mode/enforcement mismatch denied", !E({ enforcement_mode: "observe" }));
check("unknown mode denied", !E({ mode: "x", enforcement_mode: "x" }));
check("Free plan denied", !E({ plan_code: "cartel_free" }));
check("allowed 'true' string denied", !E({ allowed: "true" }));
check("UNRESTRICTED without allowed denied", !customMediaEntitled({ allowed: false, reason: "UNRESTRICTED", mode: "unrestricted" }));
check("null/array/string denied", !customMediaEntitled(null) && !customMediaEntitled([]) && !customMediaEntitled("true"));
check("NOT_MEMBER denied", !customMediaEntitled({ allowed: false, reason: "NOT_MEMBER" }));

// ---- isolation helpers
const ws = "11111111-1111-4111-8111-111111111111";
const other = "22222222-2222-4222-8222-222222222222";
const aid = "33333333-3333-4333-8333-333333333333";
const path = customMediaStoragePath(ws, aid, "gif");
check("generated path is workspace-scoped", path === `${ws}/custom-message-media/${aid}.gif`);
check("path accepted for own workspace", isWorkspaceCustomMediaPath(ws, path));
check("path rejected for foreign workspace", !isWorkspaceCustomMediaPath(other, path));
check("traversal path rejected", !isWorkspaceCustomMediaPath(ws, `${ws}/custom-message-media/../x.png`));
check("slot allowlist", isCustomMediaSlot("mission") && isCustomMediaSlot("broadcast") && !isCustomMediaSlot("inbox") && !isCustomMediaSlot(null));

// ---- server function source invariants
const bridgeAll = readFileSync("src/lib/telegram-miniapp-bridge.functions.ts", "utf8");
const fn = bridgeAll.slice(bridgeAll.indexOf("MINI-HQ B1 — prepared custom message media"));
check("B1 section present in existing bridge", fn.length > 100);
const ui = readFileSync("src/components/telegram-miniapp/MiniAppCustomMedia.tsx", "utf8");
const home = readFileSync("src/routes/tg.index.tsx", "utf8");
const sql = readFileSync("docs/sql/MINI_HQ_B1_custom_message_media.sql", "utf8");
check("initData validated before anything", /validateTelegramInitData[\s\S]*miniAppCommercialActor/.test(fn));
check("actor resolved via operator workspace RPC helper", /miniAppCommercialActor\(admin, auth\.user\.id, workspaceId\)/.test(fn));
check("upload requires entitlement", /miniAppCustomMediaUpload[\s\S]*if \(!g\.entitled\) return fail\("pro_required"\)/.test(fn));
check("select requires entitlement for non-null asset", /assetId !== null && !g\.entitled/.test(fn));
check("upload validates decoded bytes", /inspectCustomMedia\(bytes\)/.test(fn));
check("upload uses generated path, no upsert", /customMediaStoragePath\(g\.workspaceId, assetId/.test(fn) && /upsert: false/.test(fn));
check("existing private bucket reused", /"workspace-assets"/.test(fn));
check("listing workspace-bound", /eq\("workspace_id", g\.workspaceId\)/.test(fn) && /isWorkspaceCustomMediaPath\(g\.workspaceId/.test(fn));
check("no client actor/chat/path inputs", !/inputValidator\(\(input: \{[^}]*(actor|chat|path|userId)/i.test(fn) && !/telegram_chat_id/.test(fn));
check("no Telegram send in B1", !/sendPhoto|sendAnimation|sendMessage|api\.telegram\.org|functions\/v1/.test(fn + ui));
check("UI labels prepared/pending", /Prepared media only/.test(ui) && /coming later/.test(ui));
check("UI accepts only PNG/JPEG/GIF", /accept="image\/png,image\/jpeg,image\/gif"/.test(ui));
check("UI has accessible label + status", /htmlFor="miniapp-custom-media-file"/.test(ui) && /role="status"/.test(ui));
check("five primary tabs retained", /\["home", "missions", "inbox", "brand", "more"\]/.test(home));
check("panel resets per workspace", /<MiniAppCustomMedia key=\{workspaceId\}/.test(home));
check("SQL service-only", /REVOKE ALL[\s\S]*FROM PUBLIC, anon, authenticated/.test(sql) && /TO service_role;/.test(sql) && !/TO authenticated/.test(sql.replace(/FROM PUBLIC, anon, authenticated/, "")));
check("SQL fixed empty search_path + definer", /SECURITY DEFINER/.test(sql) && /SET search_path TO ''/.test(sql));
check("SQL operator or owner check", /has_platform_unrestricted_access\(_actor_user_id\), false\) IS TRUE[\s\S]*is_workspace_operator\(_workspace_id, _actor_user_id\), false\) IS TRUE/.test(sql));
check("SQL Pro gate uses positive helper", /evaluate_commercial_access\(_workspace_id, 'official_broadcasts'/.test(sql) && /custom_media_gate_ok\(v_gate\) IS NOT TRUE/.test(sql));
check("SQL exact generated path", /storage_path = \(_workspace_id::text \|\| '\/custom-message-media\/' \|\| _asset_id::text/.test(sql));
check("state always includes selected assets", /Selected assets are ALWAYS included/.test(fn));
check("UI handles query error with retry", /query\.isError/.test(ui) && /Retry/.test(ui));
check("UI explicit clear per slot", /Clear prepared \$\{slot\} media/.test(ui));
check("SQL asset same workspace + purpose + size", /workspace_id = _workspace_id/.test(sql) && /'custom_message_media'/.test(sql) && /2097152/.test(sql));
check("SQL atomic narrow JSON update", /jsonb_set\([\s\S]*'\{custom_message_media\}'/.test(sql) && !/SET metadata = '\{/.test(sql));
check("SQL no schema/RLS change", !/CREATE TABLE|ALTER TABLE|CREATE POLICY|DROP POLICY/.test(sql));
check("SQL has rollback", /Rollback:[\s\S]*DROP FUNCTION IF EXISTS public\.set_workspace_custom_message_media[\s\S]*custom_media_gate_ok/.test(sql));

// ---- senders untouched
for (const f of ["telegram-group", "social-mission-telegram", "social-mission-runner"]) {
  const src = readFileSync(`backend-source/edge-functions/${f}/index.ts`, "utf8");
  check(`${f} does not read custom media yet`, !/custom_message_media/.test(src));
}

console.log(failures.length ? `FAIL\n- ${failures.join("\n- ")}` : "");
console.log(`${passed}/${passed + failures.length} MINI-HQ B1 checks passed`);
if (failures.length) process.exit(1);
